def test_transform_v4(grid):
    """Change (4,11), (4,12), (5,11), (5,12), (6,11), (6,12) to 1 if any orthogonal neighbor is foreground"""
    result = [row[:] for row in grid]
    cells_to_check = [(4,11), (4,12), (5,11), (5,12), (6,11), (6,12)]
    for r, c in cells_to_check:
        if len(result) > r and len(result[r]) > c:
            has_fg_neighbor = False
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(result) and 0 <= nc < len(result[r]):
                    if result[nr][nc] != result[r][c]:  # Different color (neighbor is foreground)
                        has_fg_neighbor = True
                        break
            if has_fg_neighbor:
                result[r][c] = 1
    return result

